<script>import {openInstallation} from '../lib/installation-navigation.mjs';import {onMount} from 'svelte';const entries=window.PatchNotes.entries;let selected=$state(null);onMount(()=>{window.PatchNotes.markRead();window.ZonebenchShell?.({tab:'patchnotes',editor:false,version:entries[0].modVersion||entries[0].version,tabs:[],unread:false});});</script>
{#snippet entry(note)}<article class="patch-entry"><p class="patch-version">{note.version} · {note.date}</p><h2>{note.title}</h2><p class="patch-status">{note.status}</p><p class="page-lead">{note.summary}</p>{#if note.image}<figure class="patch-screenshot"><img src={note.image.src} alt={note.image.alt} width="488" height="314" loading="lazy"/>{#if note.image.caption}<figcaption class="hint">{note.image.caption}</figcaption>{/if}</figure>{/if}{#each note.sections as group}<section class="patch-group"><h3>{group.title}</h3><ul>{#each group.items as text}<li>{text}</li>{/each}</ul></section>{/each}{#if note.links}<div class="site-actions">{#each note.links as link}<a class="tool" href={link.url}>{link.label}</a>{/each}</div>{/if}</article>{/snippet}
<p class="eyebrow">SQUARED AWAY / WHAT CHANGED</p><h1>Patch Notes</h1>{@render entry(entries[0])}<section class="patch-history"><h2>Previous updates</h2><p class="hint">Choose an update to read its patch notes.</p><div class="patch-history-tiles">{#each entries.slice(1) as note}<button class="patch-history-tile" aria-expanded={selected===note.id} onclick={()=>selected=selected===note.id?null:note.id}><span class="patch-version">{note.version}</span><strong>{note.title}</strong><span class="hint">{note.date}</span></button>{/each}</div>{#if selected}<div class="patch-history-detail"><button class="tool" onclick={()=>selected=null}>Close older notes</button>{@render entry(entries.find(n=>n.id===selected))}</div>{/if}</section><a class="tool primary" href="#installation" onclick={openInstallation}>Installation guide</a>

<style>.patch-screenshot{margin:24px 0}.patch-screenshot img{display:block;max-width:100%;height:auto;border-radius:4px}.patch-screenshot figcaption{margin-top:8px}</style>
